// Configure your thresholds and connection details
const config = {
  // Update these for your setup
  host: process.env.PGHOST || 'localhost',
  port: process.env.PGPORT || 5432,
  database: process.env.PGDATABASE || 'postgres',
  user: process.env.PGUSER || 'postgres',
  // Store password in PGPASSWORD env var or n8n credentials
  thresholds: {
    maxConnectionsPercent: 80,      // alert if connections > this % of max
    replicationLagMs: 5000,         // alert if replication lag > 5 seconds
    databaseSizeMB: 10240,           // warn if any DB > 10 GB
    idleTransactionSec: 300,         // alert if idle in transaction > 5 min
  },
  telegramChatId: process.env.TELEGRAM_CHAT_ID || 'YOUR_CHAT_ID',
};

return [{ json: config }];

const raw = $input.first().json.stdout.trim();
let stats;
try {
  stats = JSON.parse(raw);
} catch {
  return [{ json: { error: 'Failed to parse psql output', raw } }];
}

const thresholds = $('Configure').first().json.thresholds;
const alerts = [];
const warnings = [];

// Check connection usage
const connPct = Math.round((stats.connections / stats.max_connections) * 100);
if (connPct >= thresholds.maxConnectionsPercent) {
  alerts.push(`🔴 Connections: ${stats.connections}/${stats.max_connections} (${connPct}%)`);
} else if (connPct >= thresholds.maxConnectionsPercent - 15) {
  warnings.push(`🟡 Connections: ${stats.connections}/${stats.max_connections} (${connPct}%)`);
}

// Check replication lag
if (stats.replication_lag > thresholds.replicationLagMs) {
  alerts.push(`🔴 Replication lag: ${(stats.replication_lag / 1000).toFixed(1)}s`);
}

// Check database sizes
for (const db of (stats.db_sizes || [])) {
  if (db.size_mb > thresholds.databaseSizeMB) {
    warnings.push(`🟡 Database ${db.name}: ${db.size_mb} MB`);
  }
}

// Check idle transactions
if (stats.idle_in_transaction > 0) {
  alerts.push(`🔴 Idle in transaction: ${stats.idle_in_transaction} sessions`);
}

const hasAlert = alerts.length > 0 || warnings.length > 0;

let message = hasAlert ? '⚠️ Postgres Health Check\n\n' : '✅ Postgres Health Check\n\n';

if (alerts.length > 0) {
  message += alerts.join('\n') + '\n';
}
if (warnings.length > 0) {
  message += warnings.join('\n') + '\n';
}
if (!hasAlert) {
  message += `🟢 Connections: ${stats.connections}/${stats.max_connections} (${connPct}%)\n`;
  message += `🟢 Replication lag: ${(stats.replication_lag / 1000).toFixed(1)}s\n`;
  message += `🟢 Idle in transaction: ${stats.idle_in_transaction}`;
}

return [{ json: { message, hasAlert, stats } }];
